import json,re,html
S=json.load(open('source.json')); R=json.load(open('reference-targets.json')); A=[]
def plain(x):return html.unescape(re.sub('<[^>]+>','',x or ''))
def paras(x):return re.findall(r'<p>(.*?)</p>',x,re.S)
def p(*v):return ''.join('<p>'+x+'</p>' for x in v)
def base(s):return {k:s[k] for k in ['code_id','source_id','source_sha256','number']}
def keep(s,why,notes):
 a=base(s);a.update(proposed_xml=None,reason=why,review_notes=notes,status='retained_unchanged',classification='retained_necessary',substantive_impact={'version':1,'classification':'retained_necessary','assessment':why,'scope_limitations':notes,'new_burdens_review':'Aucune charge nouvelle identifiée : le texte source est intégralement maintenu, sans ajout de formalité ni modification de son champ. Aucun solde global des codes n’est chiffré.','effects':[]});return a
def change(s,xml,why,notes,removed,mid,sq,pq,before,after,kind='obligation_removed',classification='material_reduction',repeal=False):
 a=base(s); a.update(proposed_xml=xml,reason=why,review_notes=notes,status='rewrite_draft')
 if repeal:a.update(change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope=removed[0])
 else:a.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
 assert sq in plain(s['source_xml']),(s['number'],'source',sq)
 assert pq in plain(xml),(s['number'],'proposed',pq)
 a['substantive_impact']={'version':1,'classification':classification,'assessment':why,'scope_limitations':notes,'new_burdens_review':'Aucune charge nouvelle identifiée : les exigences supprimées ne sont remplacées ni par un registre, ni par une déclaration ou une autorisation. Les conditions de fond et contrôles distincts restent applicables ; aucun solde national de coût n’est établi.','effects':[{'kind':kind,'measure_id':mid,'description':why,'before':before,'after':after,'unit':'legal_duty','affected_population':'Prestataires de services à la personne et leurs bénéficiaires' if '723' in s['number'] else 'Coopératives d’activité et d’emploi et entrepreneurs salariés','conditions_and_transition':'Application selon la clause transitoire du texte proposé ; droits, créances et recours antérieurs préservés dans leur champ.','replacement_or_new_burdens':'Aucune formalité équivalente de remplacement ; les obligations distinctes et les garanties conservées ne sont pas comptées comme supprimées.','source_quote':sq,'proposed_quote':pq}]};return a
for s in S:
 n=s['number']; q=paras(s['source_xml']); xml=None
 if n=='R7232-18':
  end="Le bénéfice des exonérations de cotisations de sécurité sociale mentionnées à l'article L. 241-10 du code de la sécurité sociale est acquis à compter de la date d'enregistrement de la déclaration, lorsque celle-ci est requise pour l'exonération concernée et que ses autres conditions sont remplies."
  xml=p(q[0],"La publication du récépissé au recueil des actes administratifs de la préfecture n'est pas requise.",q[2],end,"Ces dispositions s'appliquent aux déclarations enregistrées à compter de l'entrée en vigueur du décret portant la présente rédaction. Pour les déclarations déjà enregistrées dont les exonérations n'ont pas encore pris effet, celles-ci prennent effet dès cette entrée en vigueur si leurs conditions sont remplies. Les droits plus favorables, créances, restitutions et recours relatifs aux périodes antérieures sont préservés.")
  a=change(s,xml,"Réforme de fond : suppression de la publication préfectorale redondante avec la liste électronique et de l'attente du premier jour du mois suivant cette publication. L'enregistrement et l'information des organismes compétents subsistent.","Le III de L241-10 garde ses conditions de structures, tâches, rémunérations et contrats éligibles. Cette anticipation n'est ni une suppression des cotisations générales ni un report de paiement. Les autres paragraphes de L241-10 ne deviennent pas soumis à déclaration. Aucun rendement n'est chiffré.",["Suppression de la publication obligatoire du récépissé au recueil préfectoral.","Suppression de l'attente du premier jour du mois suivant la publication pour ouvrir l'exonération."],'sap-ouverture-exoneration-enregistrement',"Le bénéfice des exonérations de cotisations de sécurité sociale mentionnées à l'article L. 241-10 du code de la sécurité sociale est acquis à compter du premier jour du mois qui suit la publication du récépissé.",end,'Ouverture au premier jour du mois suivant publication, sous les conditions de L241-10.','Ouverture dès enregistrement pour les nouveaux dossiers éligibles ; pas de taux ni assiette générale modifiés.',kind='relief_extended')
  a['benefit_review']="L'avantage est l'exonération patronale de L241-10, principalement son III pour les structures déclarées. Son point de départ est avancé à l'enregistrement et les attentes en cours prennent fin à l'entrée en vigueur, sans reprise des droits plus favorables. Les exonérations, déductions et régimes publics des autres subdivisions de L241-10 gardent leurs conditions autonomes ; aucun nouvel assujettissement à déclaration n'est introduit. Les futures rémunérations éligibles du contrat unique restent couvertes."
 elif n=='R7232-19':
  t="La personne morale ou l'entrepreneur individuel qui a effectué une déclaration n'est tenu de produire ni état trimestriel d'activité, ni bilan annuel qualitatif et quantitatif, ni tableau statistique annuel au titre du présent article."
  xml=p(t,"Aucune ventilation statistique par établissement ni transmission de ces documents au préfet ou aux ministres n'est exigée.","L'apposition sur les supports commerciaux du logotype identifiant le secteur des services à la personne est facultative. Ce logotype est mis gratuitement à la disposition des personnes morales et des entrepreneurs individuels par le ministre chargé de l'économie.","Ces dispenses s'appliquent dès l'entrée en vigueur du décret portant la présente rédaction, y compris aux documents restant à produire pour une période antérieure. Aucun rattrapage n'est exigé. Les obligations de contrôle fondées sur d'autres dispositions et les droits aux avantages légalement applicables demeurent ; les recours antérieurs sont préservés, sous réserve des dispositions répressives plus douces.")
  a=change(s,xml,"Réforme de fond : retrait des trois productions statistiques, de leur ventilation et circulation obligatoires et de l'apposition commerciale du logo. La disponibilité gratuite du logo est conservée pour tous les futurs utilisateurs.","Coordination de R7232-20 pour supprimer le retrait d'avantages fondé sur ces obligations. Les données nécessaires aux contrôles fiscaux, sociaux ou de sécurité restent régies par leurs bases autonomes ; aucune économie nationale calculée.",["Suppression des états trimestriels, bilan qualitatif et quantitatif et tableau annuel ainsi que leur ventilation et transmission.","Suppression de l'apposition obligatoire du logo sur tous les supports commerciaux."],'sap-statistiques-et-logo-obligatoires-suppression',plain(q[0]).split(' Ces documents')[0],t,'États au moins trimestriels, bilan et tableau annuels pour chaque établissement ; logo obligatoire.','Aucune production statistique périodique sur ce fondement ; logo gratuit facultatif.')
 elif n=='R7232-20':
  first="La personne morale ou l'entrepreneur individuel qui cesse de remplir les conditions ou de respecter les obligations mentionnées aux 4°, 5° et 6° de l'article R. 7232-17 perd le bénéfice des dispositions de l'article L. 7233-2 et de l'article L. 241-10 du code de la sécurité sociale dans le seul champ des avantages légalement subordonnés à ces conditions ou obligations. Aucun retrait ne peut être fondé sur les productions statistiques ou l'apposition du logotype supprimées à l'article R. 7232-19."
  xml=p(first,*q[1:],"L'absence de déclaration ne prive pas des avantages pour lesquels la loi en dispense. Le contribuable de bonne foi conserve la protection prévue à l'article L. 7232-8. Ces dispositions s'appliquent aux décisions prises à compter de l'entrée en vigueur du décret portant la présente rédaction. Les effets des décisions antérieures cessent, pour les prestations et rémunérations futures, en tant qu'ils reposent exclusivement sur les obligations supprimées de l'article R. 7232-19. Les autres conditions de fond, droits, restitutions et recours antérieurs restent soumis à leurs règles propres, sous réserve des dispositions répressives plus douces.")
  a=change(s,xml,"Coordination nécessaire : retrait du motif de perte des avantages lié au reporting et au logo supprimés ; limitation des retraits aux conditions effectivement exigées pour chaque avantage. Les garanties contradictoires de quinze jours restent entières.","L7233-2 proposé distingue TVA sans exclusivité ni déclaration et crédit sans déclaration mais avec exclusivité ou dérogation. L241-10 III conserve son champ social propre. R7232-17 reste pertinent pour les avantages qui dépendent encore de ses engagements ; aucun préavis de rupture d'emploi n'est en cause.",["Suppression du motif de retrait pour méconnaissance répétée des obligations de R7232-19 désormais supprimées."],'sap-statistiques-et-logo-obligatoires-suppression',"ou qui méconnaît de façon répétée, après mise en demeure par le préfet restée sans effet, les obligations définies à l'article R. 7232-19",'Aucun retrait ne peut être fondé sur les productions statistiques ou l’apposition du logotype supprimées à l’article R. 7232-19.'.replace('’',"'"),'Perte des avantages en cas de reporting ou logo défaillant après mise en demeure.','Ce motif est écarté ; contrôle des conditions de fond et procédure contradictoire conservés.',kind='coordination',classification='coordination_only')
 elif n=='R7232-21':
  t="La publication de la décision dans des journaux aux frais de la personne morale ou de l'entrepreneur individuel n'est pas requise."
  xml=p("La décision de retrait de l'enregistrement et du bénéfice des dispositions de l'article L. 7233-2 du code du travail et de l'article L. 241-10 du code de la sécurité sociale prend effet immédiatement, dans le seul champ des avantages dont les conditions légales ne sont plus remplies. La personne morale ou l'entrepreneur individuel en informe sans délai l'ensemble des bénéficiaires de ses prestations de services par écrit, sur papier ou sur un support électronique qui leur est accessible.",t,"Le seul retrait de l'enregistrement n'emporte pas perte d'un avantage pour lequel la loi dispense de déclaration. La protection du contribuable de bonne foi prévue à l'article L. 7232-8 demeure applicable.","Ces dispositions s'appliquent aux informations et publications restant à effectuer à compter de l'entrée en vigueur du décret portant la présente rédaction, y compris après une décision antérieure. Les frais de publications déjà effectuées, les droits acquis et les recours antérieurs demeurent régis par les dispositions qui leur sont applicables.")
  a=change(s,xml,"Réforme de fond : suppression des annonces de retrait imposées aux frais du prestataire et de la lettre individuelle comme support exclusif. L'information écrite sans délai des clients et les avantages indépendants de l'enregistrement sont conservés.","La publication préfectorale de R7232-20 subsiste ; aucune nouvelle publicité ne la remplace. Le retrait ne peut neutraliser les dispenses fiscales de L7233-2 et 199 sexdecies ni la bonne foi de L7232-8. Les exonérations sociales restent appréciées selon L241-10.",["Suppression de la publication payante du retrait dans deux journaux après mise en demeure.","Suppression du support postal individuel exclusif pour informer les bénéficiaires."],'sap-retrait-publicite-payante-suppression',plain(q[1]),t,'Publication imposée dans deux journaux aux frais du prestataire après mise en demeure ; lettre individuelle.','Pas de publication payante ; information écrite accessible de chaque bénéficiaire maintenue.')
 elif n=='R7232-22':
  t="Le présent article est abrogé à compter de l'entrée en vigueur de la loi supprimant la période d'exclusion prévue à l'article L. 7232-8."
  xml=p(t,"Le délai d'un an ne fait plus obstacle à une nouvelle déclaration, y compris lorsqu'il était en cours à cette date. Les avantages sont de nouveau ouverts pour les prestations et rémunérations postérieures dès que leurs conditions légales sont remplies, sans déclaration de remplacement pour les avantages légalement dispensés de déclaration. Les droits, reprises, restitutions et recours relatifs aux périodes antérieures demeurent régis par leurs règles propres, sous réserve des dispositions répressives plus douces ; aucune restitution générale n'est instituée.")
  a=change(s,xml,"Coordination de l'abandon de l'exclusion de douze mois déjà retenu dans L7232-8 : abrogation du délai réglementaire d'un an, sans seconde mesure comptée.","L7232-8 proposé a été lu : reprise immédiate quand les conditions sont remplies et maintien du contribuable de bonne foi. La déclaration sociale de L241-10 III reste distincte de la dispense fiscale. Aucun délai d'ancienneté d'emploi ni notification de rupture n'est visé.",["Abrogation de l'interdiction de nouvelle déclaration pendant un an après notification du retrait."],'sap-fin-exclusion-douze-mois',plain(q[0]),t,'Un an à compter de la notification du retrait avant nouvelle déclaration.','Aucun délai d’exclusion ; conditions des avantages toujours exigées.',kind='coordination',classification='coordination_only',repeal=True)
 elif n=='D7233-1':
  q[2]="2° Le numéro d'enregistrement de la déclaration lorsque l'avantage concerné l'exige ainsi que le numéro de délivrance de l'agrément lorsque les activités relèvent de l'article L. 7232-1 ;"
  q[6]="6° Abrogé ;"
  q[11]="11° Lorsque les prestations n'ouvrent pas droit aux avantages fiscaux prévus par l'article L. 7233-2, les devis, factures et documents commerciaux l'indiquent. La seule absence de déclaration ne justifie pas cette indication pour un avantage dont la loi dispense de déclaration."
  t="Les dates d'enregistrement de la déclaration et de délivrance de l'agrément ainsi que le numéro d'immatriculation de l'intervenant ne sont pas exigés sur les factures émises à compter de l'entrée en vigueur du décret portant la présente rédaction."
  xml=p(*q,t,"Les factures antérieures conservent leur valeur justificative sans réédition. Les droits aux avantages, contrôles et recours demeurent dans leur champ propre.")
  a=change(s,xml,"Réforme de fond : retrait des dates administratives répétées et de l'identifiant interne du salarié sur la facture ; coordination de l'avertissement fiscal avec les dispenses de déclaration. Tous les montants, services, temps et frais utiles restent détaillés.","Les subdivisions 1° à 11° sont conservées, le 6° étant abrogé. L'agrément de protection reste distinct de la déclaration fiscale dispensée. D7233-2 continue d'imposer la présentation TTC ; aucune dispense de registre du personnel n'est créée.",["Suppression des deux dates administratives et du numéro interne d'immatriculation de l'intervenant sur la facture."],'sap-factures-mentions-redondantes-suppression',"6° Un numéro d'immatriculation de l'intervenant permettant son identification dans les registres des salariés de l'entreprise ou de l'association prestataire ;",t,'Dates administratives et identifiant salarié obligatoires sur chaque facture.','Numéros des titres utiles maintenus, dates et identifiant salarié retirés ; contenu économique conservé.')
 elif n=='D7233-4':
  t="Le présent article est abrogé à compter de l'entrée en vigueur de la dispense d'attestation fiscale distincte prévue à l'article 199 sexdecies du code général des impôts."
  xml=p(t,"Aucune attestation fiscale annuelle distincte ni récapitulatif des interventions sur ce fondement n'est exigé après cette date, y compris pour les dépenses antérieures. Les attestations déjà délivrées conservent leur valeur justificative ; aucune réédition ni régularisation des seules mentions supprimées n'est requise. Les pièces ordinaires et les autres éléments probants admis par l'article 199 sexdecies permettent de justifier les dépenses. Les crédits d'impôt, restitutions, contrôles des conditions de fond, prescriptions et recours sont préservés, y compris pour les situations futures éligibles.")
  a=change(s,xml,"Coordination nécessaire avec le 6 de 199 sexdecies proposé : abrogation de l'attestation annuelle distincte et de toutes ses mentions, sans nouvelle pièce équivalente. Ce retrait documentaire appartient à la même mesure fiscale.","Les 1° à 4° ne subsistent pas comme formulaire obligatoire : identité, paiement et prestations restent prouvables par les pièces ordinaires. Le crédit de 50 %, ses plafonds et restitutions restent ceux de 199 sexdecies, sans minimum de durée d'emploi ajouté.",["Abrogation de l'attestation fiscale annuelle distincte et de son récapitulatif nominatif détaillé des interventions."],'sap-credit-impot-dispense-attestation',plain(q[0]),t,'Attestation annuelle obligatoire avec compte débité, intervenants, dates et durées.','Justification par pièces ordinaires conformément au 6 de 199 sexdecies ; pas d’attestation distincte.',kind='coordination',classification='coordination_only',repeal=True)
 elif n=='D7233-9':
  t="Le présent article est abrogé à compter de l'entrée en vigueur du décret portant la présente abrogation."
  xml=p(t,"Aucun état récapitulatif individuel annuel distinct des aides n'est exigé sur ce fondement après cette date, y compris pour les années antérieures. Les documents déjà établis et les pièces ordinaires légalement conservées demeurent utilisables pour le contrôle. Les transmissions prévues à l'article D. 7233-10, l'information des bénéficiaires prévue à l'article D. 7233-11, les conditions et avantages de l'aide, les créances et recours restent applicables dans leur champ propre, pour les bénéficiaires actuels et futurs.")
  a=change(s,xml,"Réforme de fond : suppression de l'état individuel annuel spécialement établi pour contrôle, redondant avec les pièces de versement et les informations utiles maintenues. Les aides et leurs exclusions d'assiette restent ouvertes.","D7233-10 permet toujours la connaissance par l'entreprise des versements du CSE ; D7233-11 informe le bénéficiaire. Les pièces comptables légales ne sont pas abolies et le plafond cumulé demeure contrôlable. Coût net non chiffré.",["Suppression de l'établissement obligatoire d'un état récapitulatif individuel annuel distinct des aides versées."],'sap-aides-etat-individuel-suppression',"un état récapitulatif individuel des aides versées aux salariés de l'entreprise et aux autres personnes mentionnées à l'article L. 7233-5.",t,'État individuel annuel distinct aux fins de contrôle.','Aucun état spécial ; pièces de paiement et communications utiles conservées.',repeal=True)
 elif n=='D7233-11':
  t="La mention du montant de l'aide pour chaque bénéficiaire dans la déclaration prévue à l'article 87 du code général des impôts n'est pas exigée au titre du présent article."
  xml=p(q[0],t,"Cette dispense s'applique dès l'entrée en vigueur du décret portant la présente rédaction aux déclarations restant à souscrire, y compris pour les années antérieures, sans dépôt correctif ni rattrapage des seules mentions supprimées. Elle ne supprime pas les informations dues sur un fondement légal autonome pour des sommes imposables. Les exclusions d'assiette et le caractère non imposable de l'aide demeurent applicables aux situations futures éligibles ; les droits, contrôles, restitutions et recours relatifs aux aides antérieures sont préservés.")
  a=change(s,xml,"Réforme de fond : suppression de la rubrique déclarative spéciale des aides dans la déclaration de salaires ; maintien entier de l'attestation au bénéficiaire avant le 1er février, utile pour identifier les dépenses réellement supportées.","L'article 87, officiel et proposé, vise les rémunérations imposables et frais des dirigeants ; sa déclaration n'est pas supprimée. L'annexe III 39 et les spécifications déclaratives nécessitent la coordination de cette rubrique sans supprimer les sommes imposables autonomes ; elles ne sont pas réécrites ici.",["Suppression de la mention annuelle individuelle de l'aide dans la déclaration fiscale sur le seul fondement de D7233-11."],'sap-aides-rubrique-fiscale-suppression',plain(q[1]),t,'Mention annuelle de chaque aide dans la déclaration de l’article 87.','Plus de mention spéciale des aides exonérées sur ce fondement ; attestation au bénéficiaire conservée.')
 elif n=='R7331-2':
  t="Aucune délibération annuelle distincte sur les actions d'accompagnement et leurs ressources n'est imposée."
  xml=p("La coopérative d'activité et d'emploi assure un accompagnement individuel de chaque entrepreneur salarié en vue de favoriser le développement de son activité économique.","Les statuts de la coopérative d'activité et d'emploi déterminent les services mutualisés proposés pour l'accompagnement individuel et collectif des entrepreneurs salariés.",t,"Cette dispense s'applique aux délibérations restant à tenir à compter de l'entrée en vigueur du décret portant la présente rédaction. Les compétences de l'assemblée générale, les engagements d'accompagnement valablement souscrits et les droits des entrepreneurs salariés demeurent ; les autres délibérations légalement requises ne sont pas supprimées.")
  a=change(s,xml,"Réforme de fond : retrait de la délibération annuelle thématique imposée ; l'accompagnement individuel effectif et la définition statutaire des services sont intégralement conservés.","L7331-2 maintient les services mutualisés et l'accompagnement ; la dispense ne permet pas de supprimer les moyens contractuellement dus ni les votes budgétaires sur un fondement distinct. Elle ne fixe aucune durée à l'emploi.",["Suppression de la délibération annuelle obligatoire spécifique aux actions d'accompagnement et ressources affectées."],'cae-deliberation-annuelle-accompagnement-suppression',"L'assemblée générale délibère chaque année sur les actions nécessaires à l'accompagnement individuel et collectif des entrepreneurs salariés et les ressources à affecter à cet effet.",t,'Délibération thématique obligatoire chaque année.','Pas de cadence annuelle spécifique ; pouvoirs de l’assemblée et accompagnement subsistent.')
 elif n=='R7331-3':
  t="Ces entretiens ne sont pas soumis à l'établissement d'un document écrit ni à la signature de l'entrepreneur salarié."
  xml=p("Le contrat d'entrepreneur salarié mentionné au 2° de l'article L. 7331-2 définit les conditions dans lesquelles l'entrepreneur salarié bénéficie, par période de douze mois, d'au moins deux entretiens individuels d'accompagnement.",t,"Les entretiens portent notamment sur le bilan et les perspectives d'évolution prévisible de son activité économique, les actions individuelles et collectives nécessaires au développement de son activité économique ainsi que les besoins d'accompagnement.","La dispense de document et de signature s'applique aux entretiens tenus à compter de l'entrée en vigueur du décret portant la présente rédaction, y compris dans les contrats en cours. Les documents antérieurs conservent leur valeur probante et les droits acquis à l'accompagnement ainsi que les créances et recours antérieurs demeurent préservés.")
  a=change(s,xml,"Réforme de fond : suppression du document écrit signé obligatoire à chaque entretien. Le droit à au moins deux entretiens par douze mois et l'examen des besoins, du bilan et des perspectives restent garantis.","Le contrat écrit de L7331-2 n'est pas supprimé ; la période d'accompagnement n'est pas une durée d'emploi. Aucun nouveau compte rendu, registre ou justificatif ne remplace le document signé. La baisse porte sur le formalisme, non sur le service rendu.",["Suppression du document écrit et signé obligatoire relatif à chaque entretien individuel d'accompagnement."],'cae-entretiens-document-signe-suppression',"d'au moins deux entretiens individuels d'accompagnement faisant l'objet d'un document écrit et signé par l'entrepreneur salarié.",t,'Deux entretiens au moins par douze mois assortis d’un document signé.','Même droit aux entretiens et contenu utile ; aucun écrit signé obligatoire.')
 else:
  reasons={
  'D7233-2':("Maintien nécessaire de l'affichage TTC des prix, taux horaires et déplacements. Cette transparence protège le particulier contre un prix incomplet ; elle ne constitue ni taxe nouvelle ni double déclaration.","Le renvoi à D7233-1 reste opérant : ses 7°, 9° et 10° demeurent. Les taux de TVA et les avantages fiscaux ne sont pas modifiés par cet article."),
  'D7233-3':("Maintien nécessaire des modes de paiement traçables, y compris le CESU, ouvrant le crédit d'impôt. La règle facilite le contrôle de dépenses réellement acquittées sans imposer de déclaration supplémentaire.","La dispense de déclaration du prestataire et d'attestation distincte de 199 sexdecies ne supprime pas la preuve du paiement. Carte, prélèvement, virement, titres de paiement, chèque et CESU restent tous admis ; aucune durée d'emploi nouvelle."),
  'D7233-5':("Maintien des sous-plafonds de 500 euros, 3 000 euros et 5 000 euros et de la qualification du petit bricolage limité à deux heures. Ils bornent des activités éligibles au crédit sans supprimer son accès futur ; leur retrait isolé ne modifierait pas le renvoi fiscal figé.","199 sexdecies 3, officiel et proposé, vise la rédaction au 1er janvier 2021 de D7233-5. Une extension effective des plafonds requerrait une réforme de cette référence législative, non décidée ici. Aucun plafond ni taux nouveau inventé."),
  'D7233-6':("Maintien intégral de la faculté de financer les services à la personne dans l'entreprise. Ce droit favorable ne prescrit ni prélèvement, ni autorisation, ni reporting et reste utile aux futurs salariés éligibles.","L7233-4 lu conserve les exclusions d'assiette et les catégories financées. La localisation au sein de l'entreprise ne doit pas être supprimée au motif de simplification des aides."),
  'D7233-7':("Maintien du champ inclusif de l'aide : salariés et agents de personnes privées ou publiques et dirigeants éligibles. Réduire cette liste fermerait un avantage futur sans retirer une charge administrative.","L7233-5 lu réserve les mêmes fins et règles d'attribution et l'ouverture à tous les salariés. Le régime des agents publics ne devient pas celui du contrat privé unique."),
  'D7233-8':("Maintien du plafond annuel par bénéficiaire, de son indexation annuelle et de la limite des frais réellement supportés. L'indexation est un avantage à préserver ; la borne du coût prévient le financement de dépenses inexistantes.","La source porte 1 830 euros avec révision annuelle, non un montant actualisé à inventer. Sa note vise le 1er janvier 2026 et les périodes d'activité correspondantes ; cette date n'est pas celle de la réforme proposée. Les arrêtés d'actualisation ne sont pas fournis."),
  'D7233-10':("Maintien de la transmission ciblée du CSE à l'entreprise : identité et montant suffisent au cumul des aides et à l'information fiscale du bénéficiaire. Sa suppression compromettrait le contrôle du plafond partagé et l'attestation utile.","Les dix premiers jours de janvier restent le délai de cette transmission, distinct du préavis d'emploi. D7233-9 ne prescrit plus d'état spécial, mais le versement du CSE doit rester connu ; aucune copie de pièces supplémentaire n'est exigée."),
  'R7233-12':("Maintien intégral de l'extension favorable de l'aide publique aux chèques emploi-service universels des agents, salariés et ayants droit. Aucune procédure distincte, taxe ou échéance ne peut être retirée de ce texte d'ouverture.","Le renvoi à L7233-4 maintient exclusions d'assiette et finalités éligibles. Les agents publics et leurs ayants droit ne sont pas artificiellement soumis au contrat privé unique."),
  'D7313-1':("Maintien intégral de la rémunération moyenne des congés des VRP et de l'absence de réduction des commissions pour l'activité antérieure. Il s'agit de droits salariaux essentiels, distincts de l'indemnité ordinaire de rupture.","La période de référence reste l'année précédant le congé. L7313-6 lu concerne les représentations commerciales, non une condition d'ancienneté du congé ; sa simplification ne rend pas le renvoi vide. Le plafond de six mois de rupture ne s'applique pas ici."),
  'D7322-1':("Maintien nécessaire de l'identification du ministre chargé du travail et de la forme de ses décisions. Ce texte n'impose pas un agrément aux gérants ; il rend opératoire la protection collective de leur rémunération.","L7322-4 lu concerne l'extension des accords ou la fixation des conditions et minima des gérants non salariés après consultation. Aucun contrat salarié privé ni préavis de quinze jours n'est substitué à ce régime autonome."),
  'R7331-1':("Maintien de la prise en charge par la coopérative des obligations de l'activité de l'entrepreneur salarié. Cette attribution évite de reporter sur celui-ci des obligations fiscales, sociales et comptables ; elle ne crée pas un second ensemble de déclarations.","L7331-2 2° lu conserve le contrat écrit et définit les nouveaux emplois à durée indéterminée. Le renvoi reste pertinent. Les réformes d'IS ou de cotisations s'appliquent par leurs règles propres, sans être rétablies par cette attribution générale."),
  'R7331-4':("Maintien intégral de l'information et du conseil de santé et sécurité des entrepreneurs salariés. L'obligation préventive a une fonction essentielle ; aucune autorisation, rapport périodique ou double justificatif n'est prescrit ici.","La réserve de L7332-2 protège les obligations de sécurité distinctes. La réduction du formalisme d'accompagnement de R7331-3 ne supprime ni prévention ni responsabilité ; aucune transition d'emploi n'est affectée."),
  'R7331-5':("Maintien des deux comptes analytiques et de l'accès de l'entrepreneur à ses opérations et sa situation financière. Cette séparation protège la détermination de sa rémunération et de ses droits ; elle n'est pas un reporting public doublonné.","Les 1° et 2° restent entiers. À défaut de système, la transmission mensuelle ou sur demande utile à la gestion demeure : retirer cette solution fermerait un droit d'accès. Aucun système informatique obligatoire ni nouvelle périodicité n'est créé.")}
  a=keep(s,*reasons[n])
 A.append(a)
